class Solution {
public:
    string robotWithString(string s) {
        int n = s.size();
        vector<char> suffixMin(n);
        suffixMin[n - 1] = s[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffixMin[i] = min(s[i], suffixMin[i + 1]);
        }
        string t, p;
        for (int i = 0; i < n; i++) {
            while (!t.empty() && t.back() <= suffixMin[i]) {
                p.push_back(t.back());
                t.pop_back();
            }
            t.push_back(s[i]);
        }
        while (!t.empty()) {
            p.push_back(t.back());
            t.pop_back();
        }
        return p;
    }
};
